SELECT txn_type, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, ROUND(AVG(amount), 2) AS avg_amount, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN merchant = 'Lazada' THEN 1 END), 0), 2) AS amount_per_lazada FROM transactions GROUP BY txn_type ORDER BY txn_type DESC NULLS LAST;
